[data-brand="nara"].dark {
  --background: hsl(165 30% 6%);
  --foreground: hsl(150 20% 96%);

  --card: hsl(165 28% 9%);
  --card-foreground: hsl(150 20% 96%);

  --popover: hsl(165 28% 9%);
  --popover-foreground: hsl(150 20% 96%);

  --primary: hsl(158 64% 52%);
  --primary-foreground: hsl(165 30% 8%);

  --secondary: hsl(165 20% 16%);
  --secondary-foreground: hsl(150 20% 96%);

  --muted: hsl(165 20% 16%);
  --muted-foreground: hsl(150 12% 62%);

  --accent: hsl(165 22% 18%);
  --accent-foreground: hsl(150 20% 96%);

  --destructive: hsl(0 63% 45%);
  --destructive-foreground: hsl(0 0% 98%);

  /* โหมดมืดกลับด้าน — hover ให้ "สว่างขึ้น" */
  --primary-hover: hsl(158 64% 57%);
  --secondary-hover: hsl(165 20% 20%);
  --accent-hover: hsl(165 22% 22%);
  --destructive-hover: hsl(0 63% 50%);


  /* โหมดมืดสลับหัวท้าย — warning พื้นเป็น amber-950 ตัวอักษรเป็น amber-50 */
  --warning: hsl(21 92% 14%);
  --warning-foreground: hsl(48 100% 96%);
  --warning-border: hsl(22 78% 26%);

  --danger: hsl(25.7 11.5% 12%);
  --danger-foreground: hsl(0 85% 79%);
  --danger-border: hsl(3.3 36.7% 19.2%);

  --brand: hsl(160 39.1% 13.5%);


  /* โหมดมืด — พื้นอ่อนกลายเป็นเข้ม ตัวอักษรกลายเป็นสว่าง
     สีทึบใช้เขียวสว่างขึ้นคู่กับตัวอักษรเข้ม ตรงกับที่ --primary ของทุกแบรนด์ทำอยู่แล้ว
     ส่วน amber ใช้ค่าเดียวกับโหมดสว่าง เพราะ Radix ตั้ง amber-9 ไว้เท่ากันทั้งสองโหมด */
  --success: hsl(146 55% 10%);
  --success-foreground: hsl(142 69% 74%);
  --success-border: hsl(144 50% 24%);
  --success-solid: hsl(142 69% 58%);
  --success-solid-foreground: hsl(150 70% 11%);
  --success-solid-hover: hsl(142 69% 64%);

  --warning-solid: hsl(43 100% 62%);
  --warning-solid-foreground: hsl(22 78% 20%);
  --warning-solid-hover: hsl(43 100% 68%);

  --border: hsl(165 18% 20%);
  --input: hsl(165 18% 20%);
  --ring: hsl(158 64% 52%);

  --chart-1: hsl(158 64% 52%);
  --chart-2: hsl(200 70% 50%);
  --chart-3: hsl(40 85% 55%);
  --chart-4: hsl(280 60% 55%);
  --chart-5: hsl(350 70% 55%);

  --sidebar: hsl(165 28% 9%);
  --sidebar-foreground: hsl(150 20% 96%);
  --sidebar-primary: hsl(158 64% 52%);
  --sidebar-primary-foreground: hsl(165 30% 8%);
  --sidebar-accent: hsl(165 22% 18%);
  --sidebar-accent-foreground: hsl(150 20% 96%);
  --sidebar-border: hsl(165 18% 20%);
  --sidebar-ring: hsl(158 64% 52%);
}
